# ICPC_1444
n, m = map(int, input().split())
x = [input() for _ in range(n)]

def dfs(i, j, k=0):
    if k==7:
        return 1
    res = 0
    for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        if not (0<=i+di<n and 0<=j+dj<m):
            continue
        if x[i+di][j+dj]!="YOKOHAMA"[k+1]:
            continue
        res += dfs(i+di, j+dj, k+1)
    return res

ans = 0
for i in range(n):
    for j in range(m):
        if x[i][j]=="Y":
            ans += dfs(i, j)
print(ans)
